package com.ecopulse.controller; import com.ecopulse.dto.ConsumptionDtos; import com.ecopulse.model.User; import com.ecopulse.repository.UserRepository; import com.ecopulse.repository.BuildingRepository; import com.ecopulse.service.AnalyticsService; import com.ecopulse.service.ImportService; import com.ecopulse.service.MlClient; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.time.*; import java.util.*; @RestController @RequestMapping("/api") public class ApiController { private final AnalyticsService analytics; private final ImportService importer; private final UserRepository users; private final BuildingRepository buildings; private final MlClient ml; public ApiController(AnalyticsService a,ImportService i,UserRepository u,BuildingRepository b,MlClient m){analytics=a;importer=i;users=u;buildings=b;ml=m;} private User me(){String email=(String)SecurityContextHolder.getContext().getAuthentication().getPrincipal();return users.findByEmail(email).orElseThrow();} private Instant from(String s){return s==null?Instant.now().minus(30,java.time.temporal.ChronoUnit.DAYS):LocalDate.parse(s).atStartOfDay(ZoneOffset.UTC).toInstant();} private Instant to(String s){return s==null?Instant.now():LocalDate.parse(s).plusDays(1).atStartOfDay(ZoneOffset.UTC).toInstant();} @GetMapping("/health") public Map<String,Object> health(){return Map.of("status","UP","service","ecopulse-backend");} @GetMapping("/dashboard") public ConsumptionDtos.Summary dashboard(@RequestParam(required=false)String from,@RequestParam(required=false)String to){return analytics.summary(me().organizationId,from(from),to(to));} @GetMapping("/analytics/trends") public List<ConsumptionDtos.Point> trends(@RequestParam(required=false)String from,@RequestParam(required=false)String to){return analytics.trends(me().organizationId,from(from),to(to));} @GetMapping("/analytics/buildings") public List<ConsumptionDtos.BuildingSummary> buildingAnalytics(@RequestParam(required=false)String from,@RequestParam(required=false)String to){return analytics.byBuilding(me().organizationId,from(from),to(to));} @GetMapping("/anomalies") public List<ConsumptionDtos.AlertView> anomalies(@RequestParam(required=false)String from,@RequestParam(required=false)String to){return analytics.anomalies(me().organizationId,from(from),to(to));} @GetMapping("/forecast") public Map<?,?> forecast(@RequestParam(defaultValue="7") int horizon){ var rs=analytics.records(me().organizationId,Instant.now().minus(90,java.time.temporal.ChronoUnit.DAYS),Instant.now()); var vals=rs.stream().map(x->x.electricityKwh.doubleValue()).toList(); if(vals.size()<3)return Map.of("available",false,"message","At least three historical records are required."); try{return ml.forecast(vals,Math.min(30,Math.max(1,horizon)));}catch(Exception e){return Map.of("available",false,"message","Advanced forecasting is temporarily unavailable.");}} @GetMapping("/ai/summary") public Map<String,Object> aiSummary(){var s=analytics.summary(me().organizationId,Instant.now().minus(30,java.time.temporal.ChronoUnit.DAYS),Instant.now()); String text=String.format("In the last 30 days EcoPulse recorded %.0f kWh of electricity, %.0f L of water and %.0f kg of waste. The sustainability score is %.0f/100. Review anomaly alerts and the highest-consuming building before changing operations.",s.electricityKwh(),s.waterLiters(),s.wasteKg(),s.sustainabilityScore()); return Map.of("provider","deterministic-analytics","summary",text);} @GetMapping("/buildings") public List<com.ecopulse.model.Building> buildingList(){return buildings.findByOrganizationId(me().organizationId);} @PostMapping("/consumption/import") public Map<String,Integer> upload(@RequestParam("file") MultipartFile file)throws Exception{return importer.importCsv(me().organizationId,file);} }
